-- Faculty profiles, per-course faculty, and ASA faculty ratings, plus the
-- 2026-27 Mohali lineup refresh. Sources (ISB login required): ASA's
-- Lineup_Mohali_2026-27_Core and Elective page (exported to a sheet on
-- 2026-09-11), the Atrium Faculty list, and ASA's FacultyRatings pages
-- (offerings from AY 2021-22 on). The 13 courses missing from the new
-- lineup are deliberately left active.

alter table public.courses
  add column academic_area text,
  add column academic_associates text[] not null default '{}',
  add column overview_video_url text;

create table public.faculty (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  designation text,
  faculty_type text,
  academic_area text,
  affiliation text,
  profile_url text,
  bio_url text,
  photo_url text,
  ratings_url text,
  ratings_legacy_url text,
  sharepoint_id int,
  updated_at timestamptz not null default now()
);

create table public.course_faculty (
  course_id uuid not null references public.courses(id) on delete cascade,
  faculty_id uuid not null references public.faculty(id) on delete cascade,
  sessions text,
  affiliation text,
  sort_order int not null default 0,
  primary key (course_id, faculty_id)
);
create index course_faculty_faculty_idx on public.course_faculty (faculty_id);

create table public.faculty_ratings (
  id uuid primary key default gen_random_uuid(),
  faculty_id uuid not null references public.faculty(id) on delete cascade,
  course_code text,
  offering text not null,
  academic_year text,
  sort_key int not null default 0,
  scale smallint not null check (scale in (5, 7)),
  instructor_rating numeric(4,2),
  course_rating numeric(4,2),
  difficulty numeric(4,2),
  workload numeric(4,2),
  pace numeric(4,2),
  feedback numeric(4,2),
  enrollments int,
  respondents int,
  created_at timestamptz not null default now()
);
create index faculty_ratings_faculty_idx on public.faculty_ratings (faculty_id, sort_key desc);

-- ISB-internal data: readable only by signed-in (@isb.edu) users, never anon.
alter table public.faculty enable row level security;
alter table public.course_faculty enable row level security;
alter table public.faculty_ratings enable row level security;
create policy "signed-in users read faculty" on public.faculty for select to authenticated using (true);
create policy "signed-in users read course faculty" on public.course_faculty for select to authenticated using (true);
create policy "signed-in users read faculty ratings" on public.faculty_ratings for select to authenticated using (true);
create policy "admins manage faculty" on public.faculty for all to authenticated
  using (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin))
  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin));
create policy "admins manage course faculty" on public.course_faculty for all to authenticated
  using (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin))
  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin));
create policy "admins manage faculty ratings" on public.faculty_ratings for all to authenticated
  using (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin))
  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.is_admin));

